    const FLOAT_TOAST_MAX = 7;
    let floatToastSeq = 0;
    const activeFloatToasts = [];

    function dismissFloatToast(id, immediate) {
      const idx = activeFloatToasts.findIndex(t => t.id === id);
      if (idx < 0) return;
      const item = activeFloatToasts[idx];
      clearTimeout(item.timer);
      activeFloatToasts.splice(idx, 1);
      const el = item.el;
      if (!el) return;

      if (immediate) {
        try { el.remove(); } catch (e) {}
        return;
      }

      // Already animating out — ignore second click
      if (el.dataset.leaving === '1') return;
      el.dataset.leaving = '1';

      // Clear any inline transform/opacity so keyframes control the exit
      el.style.transition = 'none';
      el.style.transform = '';
      el.style.opacity = '';
      // Kill entrance keyframes, then play jump + swipe-left
      el.style.animation = 'none';
      void el.offsetWidth; // reflow so the new animation can restart
      el.classList.add('toast-jump-exit');
      el.style.pointerEvents = 'none';

      let removed = false;
      const cleanup = function () {
        if (removed) return;
        removed = true;
        try { el.remove(); } catch (e) {}
      };
      el.addEventListener('animationend', cleanup, { once: true });
      // Fallback if animationend is missed
      setTimeout(cleanup, 450);
    }

    function triggerDollahFloatingToast(data) {
      const stack = document.getElementById('float-toast-stack');
      if (!stack) return;

      const titleLower = String(data.title || '').toLowerCase();
      const statusLower = String(data.status || '').toLowerCase();
      const isLtc = titleLower.includes('litecoin') || titleLower.includes('ltc') || data.icon === 'Ł';
      const isBinance = titleLower.includes('binance') || data.icon === '🟡' || data.icon === 'B';
      const isPending = statusLower.includes('pending');

      let iconChar = '●';
      let iconWrapClass = 'w-11 h-11 rounded-xl bg-[#1a2433] border border-[#2a3a4c] flex items-center justify-center text-lg font-black text-slate-300 shrink-0';
      if (isLtc) {
        iconChar = 'Ł';
        iconWrapClass = 'w-11 h-11 rounded-xl bg-[#9195a1] flex items-center justify-center text-lg font-black text-white shrink-0 border-0';
      } else if (isBinance) {
        iconChar = 'B';
        iconWrapClass = 'w-11 h-11 rounded-xl bg-[#F0B90B] flex items-center justify-center text-lg font-black text-[#0b0e11] shrink-0 border-0';
      } else if (data.icon) {
        iconChar = data.icon;
      }

      let statusText = data.status || 'Complete';
      let pillHtml = '';
      let pillClass = '';
      if (isPending) {
        statusText = data.status || 'Pending Cashout';
        pillClass = 'inline-flex items-center justify-center px-2.5 py-1 rounded-full bg-[#6c5ce7] text-white text-[10px] font-extrabold uppercase tracking-wide leading-none shrink-0 shadow-sm shadow-indigo-900/40';
        pillHtml = 'Pending';
      } else {
        statusText = (isLtc || isBinance) ? 'Sent' : (data.status || 'Complete');
        pillClass = 'inline-flex items-center justify-center w-6 h-6 rounded-full bg-emerald-500 text-white shrink-0 shadow-sm shadow-emerald-900/40';
        pillHtml = '<svg class="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>';
      }

      const coinsRaw = (data.coins != null ? data.coins : '').toString();
      const timeText = String(data.time || 'just now').replace(/</g, '&lt;');
      const titleText = String(data.title || '').replace(/</g, '&lt;');
      const statusSafe = String(statusText).replace(/</g, '&lt;');
      const coinsSafe = coinsRaw.replace(/</g, '&lt;');

      while (activeFloatToasts.length >= FLOAT_TOAST_MAX) {
        dismissFloatToast(activeFloatToasts[0].id, true);
      }

      const id = 'ft_' + (++floatToastSeq) + '_' + Date.now();
      const card = document.createElement('div');
      card.className = 'float-toast-card toast-with-timer';
      card.dataset.toastId = id;
      card.setAttribute('role', 'status');
      card.onclick = function (ev) {
        if (ev) { ev.preventDefault(); ev.stopPropagation(); }
        dismissFloatToast(id, false);
      };
      card.title = 'Click to dismiss';
      card.innerHTML = `
        <div class="flex items-start justify-between gap-3 mb-2.5">
          <span class="text-[11px] text-slate-400 font-medium pt-0.5">${timeText}</span>
          <div class="${pillClass}">${pillHtml}</div>
        </div>
        <div class="flex items-start gap-3">
          <div class="${iconWrapClass}"><span>${iconChar}</span></div>
          <div class="min-w-0 flex-1 pt-0.5">
            <h4 class="text-[14px] font-bold text-white truncate leading-tight">${titleText}</h4>
            <p class="text-[12px] text-slate-400 mt-0.5 truncate">${statusSafe}</p>
            <p class="coin-amt text-[13px] font-black mt-1.5 flex items-center gap-1.5">
              ${coinIconSvg('coin-icon-sm')}
              <span>${coinsSafe}</span>
            </p>
          </div>
        </div>
        <div class="toast-progress-track" aria-hidden="true">
          <span class="toast-progress-bar run" style="animation-duration:${TOAST_DURATION_MS}ms"></span>
        </div>
      `;

      stack.appendChild(card);
      const timer = setTimeout(() => dismissFloatToast(id, false), TOAST_DURATION_MS);
      activeFloatToasts.push({ id, el: card, timer });
    }

