    // ── Network postbacks (client / return-URL style) ──
    // Ovnix dashboard Postback URL example (no separate PHP):
    //   https://gollah.com/?pb=ovnix&sub1={sub1}&reward={rewardValue}&offer_name={offer_name}&transaction_id={transaction_id}
    // Other networks can use the same ?pb= provider flag.
    const POSTBACK_TXN_KEY = 'gollah_pb_txns_v1';
    function loadPostbackTxns() {
      try { return new Set(JSON.parse(localStorage.getItem(POSTBACK_TXN_KEY) || '[]')); } catch (e) { return new Set(); }
    }
    function savePostbackTxn(txn) {
      if (!txn) return;
      try {
        const s = loadPostbackTxns();
        s.add(String(txn));
        const arr = [...s].slice(-200);
        localStorage.setItem(POSTBACK_TXN_KEY, JSON.stringify(arr));
      } catch (e) {}
    }
    function hasPostbackTxn(txn) {
      if (!txn) return false;
      return loadPostbackTxns().has(String(txn));
    }

    async function handleOvnixPostbackParams(params) {
      const sub1 = params.get('sub1') || params.get('user_id') || params.get('uid') || '';
      const reward = Number(params.get('reward') || params.get('rewardValue') || params.get('payout') || params.get('amount') || params.get('coins') || 0);
      const txn = params.get('transaction_id') || params.get('txn_id') || params.get('trans_id') || params.get('event_id') || '';
      const offerName = params.get('offer_name') || params.get('offer') || params.get('campaign') || 'Ovnix Offer';
      const status = String(params.get('status') || params.get('event') || 'completed').toLowerCase();

      if (!reward || reward <= 0) return false;
      if (['rejected', 'chargeback', 'reversed', 'cancel', 'cancelled'].includes(status)) return false;
      if (txn && hasPostbackTxn('ovnix:' + txn)) return false;

      // Only credit if logged-in user matches sub1 (when sub1 is present)
      if (sub1 && currentUser && String(currentUser.id) !== String(sub1)) {
        console.warn('[postback] Ovnix sub1 mismatch', sub1, currentUser && currentUser.id);
        return false;
      }
      if (!currentUser) {
        // Store pending for after login
        try {
          localStorage.setItem('gollah_pending_pb', JSON.stringify({
            provider: 'Ovnix', offerName, coins: Math.floor(reward), txn, at: Date.now()
          }));
        } catch (e) {}
        return false;
      }

      if (txn) savePostbackTxn('ovnix:' + txn);
      await window.creditOfferPostback(offerName, Math.floor(reward), 'Ovnix');
      return true;
    }

    async function processIncomingPostbacks() {
      try {
        const params = new URLSearchParams(window.location.search || '');
        // Also parse hash query: #surveys?status=success
        let hashParams = new URLSearchParams();
        try {
          const hash = String(window.location.hash || '');
          const qi = hash.indexOf('?');
          if (qi >= 0) hashParams = new URLSearchParams(hash.slice(qi + 1));
          else if (hash.includes('status=')) hashParams = new URLSearchParams(hash.replace(/^#/, ''));
        } catch (e) {}

        const pb = (params.get('pb') || params.get('provider') || '').toLowerCase();
        // Also detect Ovnix-style params without pb flag
        const looksOvnix = params.has('rewardValue') || params.has('reward') || (params.has('sub1') && params.has('reward'));
        if (pb === 'ovnix' || (looksOvnix && (pb === '' || pb === 'ovnix'))) {
          const ok = await handleOvnixPostbackParams(params);
          if (ok) {
            // Clean query from address bar
            try {
              const clean = window.location.pathname + (window.location.hash || '');
              window.history.replaceState({}, document.title, clean || '/');
            } catch (e) {}
          }
        }

        // TheoremReach redirect return — S2S already credited coins; refresh balance + toast
        const trStatus = (params.get('status') || hashParams.get('status') || '').toLowerCase();
        const trHashPath = String(window.location.hash || '').toLowerCase();
        if (trStatus === 'success' || trHashPath.includes('status=success') || params.get('pb') === 'theoremreach') {
          if (currentUser && db) {
            try {
              const { data: profile } = await db.from('profiles').select('coins, level').eq('id', currentUser.id).single();
              if (profile && Number(profile.coins) >= 0) {
                userCoins = Number(profile.coins) || 0;
                updateHeaderCoinsDisplay();
                updateLevelAndXpUI(userCoins);
              }
            } catch (e) {}
          }
          if (typeof showMiniToast === 'function') {
            showMiniToast('Survey complete', 'Rewards credit via secure postback shortly', 'success');
          }
          try {
            if (trHashPath.includes('surveys')) {
              if (typeof filterCategory === 'function') filterCategory('surveys');
              if (typeof navigate === 'function') navigate('home');
            }
            // Clean status from hash/query without dropping path
            const cleanHash = (window.location.hash || '').replace(/[?&]status=[^&]*/g, '').replace(/\?$/, '');
            window.history.replaceState({}, document.title, window.location.pathname + cleanHash);
          } catch (e) {}
        }

        // Apply pending postback after login
        try {
          const raw = localStorage.getItem('gollah_pending_pb');
          if (raw && currentUser) {
            const p = JSON.parse(raw);
            if (p && p.coins > 0 && (!p.txn || !hasPostbackTxn((p.provider || 'net') + ':' + p.txn))) {
              if (p.txn) savePostbackTxn((p.provider || 'net') + ':' + p.txn);
              await window.creditOfferPostback(p.offerName || 'Offer', Math.floor(p.coins), p.provider || 'Ovnix');
            }
            localStorage.removeItem('gollah_pending_pb');
          }
        } catch (e) {}
      } catch (e) {
        console.warn('postback parse failed', e);
      }
    }

    window.creditOfferPostback = async function(offerName, coins, providerName) {
      if (!currentUser) return;
      userCoins += coins;
      updateHeaderCoinsDisplay();
      const newLvl = updateLevelAndXpUI(userCoins);

      // Match provider from known offers if not passed
      let provider = providerName || 'Network';
      const matched = ALL_OFFERS.find(o => o.name === offerName || o.name.toLowerCase() === String(offerName).toLowerCase());
      if (matched) provider = matched.provider;

      // Save to permanent completed-offers history (Profile → Earnings)
      userCompletedOffers.unshift({
        id: 'o_' + Date.now(),
        name: offerName,
        provider: provider,
        coins: coins,
        status: 'complete',
        created_at: new Date().toISOString()
      });
      saveCompletedOffersToStorage();

      if (db) {
        await db.from('profiles').update({ coins: userCoins, level: newLvl }).eq('id', currentUser.id);
      }

      const completeVisual = resolveOfferVisual({ name: offerName, id: null, provider: provider });
      addNotification({
        title: offerName,
        message: 'Complete',
        status: 'complete',
        category: 'personal',
        coins: coins,
        icon: (provider || 'G').slice(0, 2).toUpperCase(),
        image: completeVisual.image || null,
        emoji: completeVisual.emoji || null,
        emojiBg: completeVisual.emojiBg || null
      });

      broadcastLiveActivity('Offer', coins, '⚡', 'Complete', {
        username: getDisplayUsername(),
        offerName: offerName,
        provider: provider
      });
      playCompletedCustomAudio();
      triggerDollahFloatingToast({
        time: 'just now',
        title: offerName,
        status: 'Complete',
        coins: coins.toLocaleString()
      });

      if (currentTab === 'profile') renderProfile();
    };

    // CASHOUT ENGINE
