    async function submitCustomWithdrawal() {
      if (!currentUser) return;
      const amount = parseInt(document.getElementById('cashout-amount-input').value) || 0;
      const address = document.getElementById('cashout-address-input').value.trim();

      if (amount < cashoutMinCoins) {
        showAppAlert(`Minimum withdrawal for ${selectedCashoutCrypto} is ${cashoutMinCoins} Coins.`, { title: 'Minimum limit', type: 'warning' });
        return;
      }

      if (amount > userCoins) {
        showAppAlert(`Insufficient coins. You have ${userCoins.toLocaleString()} coins.`, { title: 'Insufficient balance', type: 'error' });
        return;
      }

      if (!address || address.length < 5) {
        showAppAlert("Please enter a valid wallet address or Binance ID.", { title: 'Invalid address', type: 'warning' });
        return;
      }

      const submitBtn = document.getElementById('cashout-submit-btn');
      submitBtn.innerText = "Processing...";
      submitBtn.disabled = true;

      try {
        playCashoutClickSound();

        userCoins -= amount;
        updateHeaderCoinsDisplay();

        const usdValueNum = parseFloat((amount / 1000).toFixed(2));

        const newRecordLoc = {
          id: 'w_' + Date.now(),
          user_id: currentUser.id,
          method: selectedCashoutCrypto,
          address: address,
          amount: amount,
          status: 'PENDING'
        };

        userWithdrawals.unshift(newRecordLoc);
        saveWithdrawalsToStorage();

        addNotification({
          title: selectedCashoutCrypto.includes('Binance') ? 'Binance Pay' : 'LTC',
          message: 'Pending approval',
          status: 'pending',
          category: 'personal',
          coins: amount,
          icon: selectedCashoutCrypto.includes('Binance') ? 'B' : 'Ł'
        });

        if (db) {
          await db.from('profiles').update({ coins: userCoins }).eq('id', currentUser.id);
          await db.from('withdrawals').insert({
            user_id: currentUser.id,
            method: selectedCashoutCrypto,
            destination_address: address,
            coins_amount: amount,
            usd_value: usdValueNum,
            status: 'PENDING'
          });
        }

        closeCashoutModal();

        // Push to SHARED live ticker for all users
        const shortMethod = selectedCashoutCrypto.includes('Binance') ? 'Binance' : 'LTC';
        const tickerIcon = selectedCashoutCrypto.includes('Binance') ? 'B' : 'Ł';
        broadcastLiveActivity(shortMethod, amount, tickerIcon, 'Pending', {
          username: getDisplayUsername()
        });

        triggerDollahFloatingToast({
          time: 'just now',
          title: `${selectedCashoutCrypto} Cashout`,
          status: 'Pending Cashout',
          coins: amount.toLocaleString(),
          icon: tickerIcon
        });

        await fetchUserWithdrawals();
        if (currentTab === 'profile') renderProfile();
      } catch (e) {
        showAppAlert("Withdrawal Error: " + e.message, { title: 'Error', type: 'error' });
      } finally {
        submitBtn.innerText = "Cashout";
        submitBtn.disabled = false;
      }
    }

    // FETCH PERMANENT WITHDRAWALS FROM SUPABASE DATABASE
    async function fetchUserWithdrawals() {
      if (!currentUser) return;
      if (!db) {
        try {
          const stored = localStorage.getItem(`gollah_withdrawals_${currentUser.id}`);
          if (stored) userWithdrawals = JSON.parse(stored);
        } catch (e) {}
        return;
      }

      try {
        const { data, error } = await db.from('withdrawals')
          .select('*')
          .eq('user_id', currentUser.id)
          .order('created_at', { ascending: false });

        if (!error && data) {
          const fetchedList = data.map(d => ({
            id: d.id,
            method: d.method,
            amount: d.coins_amount,
            address: d.destination_address,
            status: (d.status || 'PENDING').toUpperCase()
          }));

          // Compare with local cache to detect newly completed status for custom completed audio & live ticker broadcast
          fetchedList.forEach(fw => {
            const oldW = userWithdrawals.find(ow => String(ow.id) === String(fw.id));
            const wasPending = !oldW || (oldW.status || '').toUpperCase() === 'PENDING';
            if (wasPending && fw.status === 'COMPLETED') {
              playCompletedCustomAudio();
              const shortMethod = (fw.method || '').includes('Binance') ? 'Binance' : 'LTC';
              const tickerIcon = shortMethod === 'Binance' ? 'B' : 'Ł';
              const amtNum = Number(fw.amount) || 0;
              const amtStr = amtNum.toLocaleString();

              // Upgrade matching PENDING notification → completed (admin released payout)
              let upgraded = false;
              userNotifications.forEach(n => {
                const st = (n.status || '').toLowerCase();
                if (st !== 'pending') return;
                const nAmt = n.coins != null ? Number(n.coins) : parseNotifAmount(n.message);
                if (nAmt != null && nAmt === amtNum) {
                  n.status = 'completed';
                  n.category = 'personal';
                  n.title = shortMethod;
                  n.message = 'Complete';
                  n.coins = amtNum;
                  n.time = 'just now';
                  upgraded = true;
                }
              });
              if (!upgraded) {
                addNotification({
                  title: shortMethod,
                  message: 'Complete',
                  status: 'completed',
                  category: 'personal',
                  coins: amtNum,
                  icon: tickerIcon
                });
              } else {
                saveNotificationsToStorage();
                updateNotificationsBadge();
              }

              // Success float: short title + Sent + solid green check (no COMPLETE text)
              triggerDollahFloatingToast({
                time: 'just now',
                title: shortMethod,
                status: 'Sent',
                coins: amtStr,
                icon: tickerIcon
              });
              // Broadcast completed payout to SHARED live bar for all users
              broadcastLiveActivity(shortMethod, fw.amount, tickerIcon, 'Sent', {
                username: getDisplayUsername()
              });
            }
          });

          userWithdrawals = fetchedList;
          saveWithdrawalsToStorage();
          if (currentTab === 'profile') renderProfile();
        }
      } catch (e) {
        try {
          const stored = localStorage.getItem(`gollah_withdrawals_${currentUser.id}`);
          if (stored) userWithdrawals = JSON.parse(stored);
        } catch (err) {}
      }
    }

    // AUTO-POLLING SYNC ENGINE: Checks Supabase every 3 seconds for permanent sync & instant completed alerts
    let syncInterval = null;
    function startAutoSyncEngine() {
      if (syncInterval) clearInterval(syncInterval);
      syncInterval = setInterval(() => {
        if (currentUser) {
          fetchUserWithdrawals();
        }
      }, 3000);
    }

    window.completeUserWithdrawal = async function(withdrawalId) {
      if (!db || !currentUser) return;
      await db.from('withdrawals').update({ status: 'COMPLETED' }).eq('id', withdrawalId);
      await fetchUserWithdrawals();
    };

    function filterCategory(cat) {
      currentCategory = cat;
      const categories = ['featured', 'all', 'apps', 'games', 'surveys', 'gpt', 'signups'];
      categories.forEach(c => {
        const el = document.getElementById('cat-' + c);
        if (el) {
          if (c === cat) el.className = "cat-active w-full flex items-center justify-between px-3 py-2 text-slate-400 hover:text-white rounded-lg hover:bg-[#141d26] transition text-left";
          else el.className = "w-full flex items-center justify-between px-3 py-2 text-slate-400 hover:text-white rounded-lg hover:bg-[#141d26] transition text-left";
        }
      });
      if (currentTab !== 'home') navigate('home');
      else renderHome();
    }

    function handleOfferSearch(q) {
      searchQuery = q.toLowerCase().trim();
      if (currentTab !== 'home') navigate('home');
      else renderHome();
    }

    function updateLevelAndXpUI(earnedCoins) {
      const totalXp = Math.floor(earnedCoins / 1000);
      const currentLevel = 1 + Math.floor(totalXp / 10);
      const xpInCurrentLevel = totalXp % 10;
      const progressPercent = Math.min((xpInCurrentLevel / 10) * 100, 100);

      const levelBadge = document.getElementById('profile-level-badge');
      if (levelBadge) levelBadge.innerText = `Lvl ${currentLevel}`;

      const xpText = document.getElementById('xp-text');
      const nextLevelText = document.getElementById('xp-next-level');
      const progressBar = document.getElementById('xp-progress-bar');
      const xpNeeded = document.getElementById('xp-needed');

      // Dollah-style: left = current lvl, right = next lvl
      if (xpText) xpText.innerText = `Lvl ${currentLevel}`;
      if (nextLevelText) nextLevelText.innerText = `Lvl ${currentLevel + 1}`;
      if (progressBar) progressBar.style.width = `${progressPercent}%`;
      if (xpNeeded) xpNeeded.innerText = `${10 - xpInCurrentLevel} XP to Lvl ${currentLevel + 1}`;

      return currentLevel;
    }

    async function getUserCountry() {
      try {
        const r1 = await fetch('https://ipwho.is/');
        if (r1.ok) {
          const d1 = await r1.json();
          if (d1 && d1.country_code) return d1.country_code;
        }
      } catch (e) {}

      try {
        const r2 = await fetch('https://get.geojs.io/v1/ip/country.json');
        if (r2.ok) {
          const d2 = await r2.json();
          if (d2 && d2.country) return d2.country;
        }
      } catch (e) {}

      return 'BD';
    }

